import { BrowserRouter, Routes, Route } from "react-router-dom";
import Login from "./demofrontlogin";
import Main from "./mainHomePage";
import EditorPage from "./components/editor";
import ProtectedRoute from "./protect/ProtectedRoute";

function App() {
  return (
    <BrowserRouter>
      <Routes>

        {/* Login Page */}
        <Route path="/" element={<Login />} />

        {/* Home Page */}
        <Route
          path="/home"
          element={
            <ProtectedRoute>
              <Main />
            </ProtectedRoute>
          }
        />

        {/* Editor Page */}
        <Route
          path="/editor"
          element={
            <ProtectedRoute>
              <EditorPage />
            </ProtectedRoute>
          }
        />

        {/* Fallback */}
        <Route path="*" element={<Login />} />

      </Routes>
    </BrowserRouter>
  );
}

export default App;
